from pathlib import Pathfrom pipeline_api import RealtimeMappingPipelinefrom mesh_refine_adapter_slim import refine_mesh_in_memoryBASE_DIR = Path(__file__).resolve().parentdef main():    # ============================================================    # 阶段 1+2：实时采集 + 建图（原本逻辑，完全不动）    # ============================================================    pipeline = RealtimeMappingPipeline()    result = pipeline.run_forever(        save_mesh=True,        final_mesh_prefix="fusion_model_final",    )    # ============================================================    # 阶段 3：从 mapper 内存抽 mesh，直接优化（slim 版）    # ============================================================    print("\n🔄 进入在线优化阶段...")    if pipeline.mapper is None:        print("❌ mapper 不存在，跳过优化")        return    try:        final_mesh = pipeline.mapper.volume.extract_triangle_mesh()        final_mesh.compute_vertex_normals()    except Exception as e:        print(f"❌ 无法从 mapper.volume 抽 mesh: {e}")        return    if len(final_mesh.vertices) == 0:        print("⚠️ TSDF volume 为空，无可优化模型")        return    refined_mesh, meta = refine_mesh_in_memory(        final_mesh,        output_dir=str(BASE_DIR / "outputs_online"),        prefix="fusion_refined",        save_files=True,        save_raw=True,        verbose=True,        # ---- 推荐参数（slim 版只支持这些）----        sensor_origin="0,0,0",        use_distance_strategy=True,        # 如果想换 preset 可以加: preset="fast" / "detail" / "balanced"    )    if not meta.get("skipped"):        print(f"\n🎉 全流程完成！")        print(f"   原始 mesh:  {meta['before']['vertices']} 顶点")        print(f"   优化 mesh:  {meta['after']['vertices']} 顶点")        print(f"   优化耗时:   {meta['total_elapsed_sec']}s")        print(f"   保存位置:   {meta.get('refined_latest_path')}")if __name__ == "__main__":    main()